  1  "use client";
  2  
  3  import Link from "next/link";
  4  import { useCallback, useEffect, useRef, useState, type FormEvent } from "react";
  5  
  6  import HashValue from "@/components/evaluation/hash-value";
  7  import { EmptyState, ErrorState, InlineError, LoadingState, Panel, SessionRequired } from "@/components/ui/states";
  8  import { ApiError, toApiError } from "@/lib/api/client";
  9  import { EvaluationDataset, createDataset, listDatasets } from "@/lib/api/evaluation";
 10  import { useFrontendSession } from "@/components/providers/session-provider";
 11  import { useI18n } from "@/i18n/provider";
 12  
 13  export default function EvaluationDatasetsPage() {
 14    const { t, formatDateTime } = useI18n();
 15    const { workspaceId, accessToken, connected, sessionId } = useFrontendSession();
 16    const [datasets, setDatasets] = useState<EvaluationDataset[]>([]);
 17    const [total, setTotal] = useState<number | null>(null);
 18    const [extraPages, setExtraPages] = useState<EvaluationDataset[][]>([]);
 19    const [loadingMore, setLoadingMore] = useState(false);
 20    const [hasMore, setHasMore] = useState(true);
 21    const [error, setError] = useState<ApiError | null>(null);
 22    const [loading, setLoading] = useState(false);
 23    const [loaded, setLoaded] = useState(false);
 24  
 25    const [showForm, setShowForm] = useState(false);
 26    const [name, setName] = useState("");
 27    const [description, setDescription] = useState("");
 28    const [creating, setCreating] = useState(false);
 29    const [createError, setCreateError] = useState<ApiError | null>(null);
 30    const [createdNotice, setCreatedNotice] = useState(false);
 31    const activeSessionRef = useRef(sessionId);
 32    activeSessionRef.current = sessionId;
 33    const listGenerationRef = useRef(0);
 34  
 35    useEffect(() => {
 36      listGenerationRef.current += 1;
 37      setLoadingMore(false);
 38      setDatasets([]);
 39      setExtraPages([]);
 40      setTotal(null);
 41      setHasMore(true);
 42      setError(null);
 43      setLoading(false);
 44      setLoaded(false);
 45      setShowForm(false);
 46      setName("");
 47      setDescription("");
 48      setCreating(false);
 49      setCreateError(null);
 50      setCreatedNotice(false);
 51    }, [sessionId]);
 52  
 53    const loadMore = useCallback(async () => {
 54      if (!connected || loading || loadingMore) return;
 55      const requestSessionId = sessionId;
 56      const generation = ++listGenerationRef.current;
 57      setLoadingMore(true);
 58      try {
 59        const offset = datasets.length + extraPages.flat().length;
 60        const page = await listDatasets({ workspaceId, accessToken }, { limit: 50, offset });
 61        if (activeSessionRef.current !== requestSessionId || listGenerationRef.current !== generation) return;
 62        setExtraPages((current) => [...current, page.items]);
 63        setTotal(page.total);
 64        setHasMore(page.items.length === 50 && offset + page.items.length < page.total);
 65      } catch (caught) {
 66        if (activeSessionRef.current === requestSessionId && listGenerationRef.current === generation) setError(toApiError(caught, ""));
 67      } finally {
 68        if (activeSessionRef.current === requestSessionId && listGenerationRef.current === generation) setLoadingMore(false);
 69      }
 70    }, [connected, datasets.length, extraPages, loading, loadingMore, workspaceId, accessToken, sessionId]);
 71  
 72    const refresh = useCallback(async () => {
 73      setError(null);
 74      if (!connected) return;
 75      const requestSessionId = sessionId;
 76      const generation = ++listGenerationRef.current;
 77      setLoadingMore(false);
 78      setLoading(true);
 79      try {
 80        const page = await listDatasets({ workspaceId, accessToken }, { limit: 50 });
 81        if (activeSessionRef.current !== requestSessionId || listGenerationRef.current !== generation) return;
 82        setDatasets(page.items);
 83        setTotal(page.total);
 84        setExtraPages([]);
 85        setHasMore(page.items.length < page.total);
 86        setLoaded(true);
 87      } catch (caught) {
 88        if (activeSessionRef.current === requestSessionId && listGenerationRef.current === generation) setError(toApiError(caught, ""));
 89      } finally {
 90        if (activeSessionRef.current === requestSessionId && listGenerationRef.current === generation) setLoading(false);
 91      }
 92    }, [connected, workspaceId, accessToken, sessionId]);
 93  
 94    useEffect(() => {
 95      if (connected && !loaded) void refresh();
 96    }, [connected, loaded, refresh]);
 97  
 98    async function submitCreate(event: FormEvent<HTMLFormElement>) {
 99      event.preventDefault();
100      setCreateError(null);
101      if (!name.trim()) return;
102      const requestSessionId = sessionId;
103      setCreating(true);
104      try {
105        await createDataset({ workspaceId, accessToken }, { name: name.trim(), description: description.trim() || null });
106        if (activeSessionRef.current !== requestSessionId) return;
107        setName("");
108        setDescription("");
109        setShowForm(false);
110        setCreatedNotice(true);
111        await refresh();
112      } catch (caught) {
113        const apiError = toApiError(caught, "");
114        if (activeSessionRef.current === requestSessionId) setCreateError(apiError);
115      } finally {
116        if (activeSessionRef.current === requestSessionId) setCreating(false);
117      }
118    }
119  
120    if (!connected) {
121      return (
122        <div className="page">
123          <header className="page-header">
124            <h1>{t("evaluation.datasets.title")}</h1>
125          </header>
126          <SessionRequired contextKey="session.context.evaluations" />
127        </div>
128      );
129    }
130  
131    const visible = [...datasets];
132    for (const extra of extraPages) {
133      for (const item of extra) {
134        if (!visible.some((d) => d.id === item.id)) visible.push(item);
135      }
136    }
137  
138    return (
139      <div className="page">
140        <header className="page-header">
141          <h1>{t("evaluation.datasets.title")}</h1>
142        </header>
143  
144        <Panel
145          ariaLabel={t("evaluation.datasets.title")}
146          actions={
147            <button type="button" className="button button-primary" onClick={() => setShowForm((v) => !v)}>
148              {t("evaluation.datasets.create")}
149            </button>
150          }
151        >
152          {createdNotice && <p className="inline-notice">{t("evaluation.datasets.createdNotice")}</p>}
153  
154          {showForm && (
155            <form className="eval-form" onSubmit={submitCreate} noValidate>
156              <label>
157                {t("evaluation.datasets.nameLabel")}
158                <input required value={name} onChange={(e) => setName(e.target.value)} spellCheck={false} />
159              </label>
160              <label>
161                {t("evaluation.datasets.descriptionLabel")}
162                <textarea
163                  rows={2}
164                  value={description}
165                  onChange={(e) => setDescription(e.target.value)}
166                  placeholder={t("evaluation.datasets.descriptionPlaceholder")}
167                />
168              </label>
169              <InlineError error={createError} fallback={t("errors.requestFailed")} />
170              <div className="form-actions">
171                <button type="submit" className="button button-primary" disabled={creating || !name.trim()}>
172                  {creating ? t("evaluation.datasets.creating") : t("evaluation.datasets.create")}
173                </button>
174              </div>
175            </form>
176          )}
177  
178          {error && (
179            <ErrorState code={error.code} message={error.message || t("errors.loadEvaluation")} onRetry={() => void refresh()} />
180          )}
